CREATE ROLE brc_owner;
CREATE ROLE brc_caller;
ALTER FUNCTION initcap(text) STABLE COST 5 PARALLEL RESTRICTED LEAKPROOF;
ALTER FUNCTION generate_series(integer, integer) ROWS 10;
ALTER FUNCTION initcap(text) ROWS 10;
ALTER FUNCTION initcap(text) OWNER TO brc_owner;
SELECT provolatile, proisstrict, procost, prorows, proparallel, proleakproof, prosecdef, proconfig, proowner::regrole, proacl FROM pg_proc WHERE oid = 'initcap(text)'::regprocedure;
SELECT prorows FROM pg_proc WHERE oid = 'generate_series(integer, integer)'::regprocedure;
CREATE TABLE brc_generated(a text, b text GENERATED ALWAYS AS (initcap(a)) STORED);
CREATE TABLE brc_stats(a integer, t timestamptz, s text);
CREATE STATISTICS brc_stats_now ON (t > now()), a FROM brc_stats;
DROP TABLE brc_stats;
ALTER FUNCTION initcap(text) STABLE OWNER TO postgres;
REVOKE EXECUTE ON FUNCTION sha224(bytea) FROM PUBLIC;
SELECT proacl FROM pg_proc WHERE oid = 'sha224(bytea)'::regprocedure;
GRANT EXECUTE ON FUNCTION sha224(bytea) TO brc_caller WITH GRANT OPTION;
SELECT proacl FROM pg_proc WHERE oid = 'sha224(bytea)'::regprocedure;
SET ROLE brc_owner;
SELECT sha224('a');
SELECT has_function_privilege('sha224(bytea)', 'execute');
GRANT EXECUTE ON FUNCTION sha224(bytea) TO brc_owner;
ALTER FUNCTION sha224(bytea) STABLE;
ALTER FUNCTION initcap(text) IMMUTABLE;
RESET ROLE;
SET ROLE brc_caller;
SELECT sha224('a');
GRANT EXECUTE ON FUNCTION sha224(bytea) TO brc_owner;
RESET ROLE;
SELECT proacl FROM pg_proc WHERE oid = 'sha224(bytea)'::regprocedure;
SELECT has_function_privilege('brc_owner', 'sha224(bytea)', 'execute'), has_function_privilege('brc_caller', 'sha224(bytea)', 'execute WITH GRANT OPTION');
REVOKE EXECUTE ON FUNCTION sha224(bytea) FROM brc_caller CASCADE;
GRANT EXECUTE ON FUNCTION sha224(bytea) TO PUBLIC;
SELECT proacl FROM pg_proc WHERE oid = 'sha224(bytea)'::regprocedure;
GRANT EXECUTE ON FUNCTION initcap(text) TO brc_caller;
ALTER FUNCTION initcap(text) OWNER TO brc_owner;
SELECT proowner::regrole, proacl FROM pg_proc WHERE oid = 'initcap(text)'::regprocedure;
DROP OWNED BY brc_owner;
REASSIGN OWNED BY brc_owner TO postgres;
DROP OWNED BY brc_caller;
SELECT proowner::regrole, proacl FROM pg_proc WHERE oid = 'initcap(text)'::regprocedure;
ALTER FUNCTION initcap(text) IMMUTABLE COST 1 PARALLEL SAFE NOT LEAKPROOF;
ALTER FUNCTION generate_series(integer, integer) ROWS 1000;
DROP ROLE brc_owner;
DROP ROLE brc_caller;
